#include <Native/JasStreamPcm.hpp>
#include "assets.hpp"
#include <Native/HeapPlacement.hpp>
#include <Native/JasStreamEndian.hpp>
#include <cstdio>
int main(int argc,char**argv){try{assetCheck(argc==2,"Expected WBFS");WiiAssets disc(std::filesystem::u8path(argv[1]));unsigned count=0,shorts=0;for(const auto&file:disc.files){if(file.path.rfind("/AudioRes/Stream/",0))continue;extent(0,64,file.size);auto bytes=disc.read(file.offset,64);JASAramStream::Header h{};assetCheck(Native::decodeJasStreamHeader(bytes.data(),bytes.size(),h),"Retail header rejected");assetCheck(Native::validJasStreamBlockSize(h.block_size,h.format),"Retail block size invalid");const uint64_t length=32+uint64_t(h.block_size)*h.channels;extent(64,length,file.size);auto block=disc.read(file.offset+64,size_t(length));JASAramStream::BlockHeader bh{};assetCheck(Native::decodeJasStreamBlock(block.data(),block.size(),h.channels,h.block_size,bh),"Retail first block rejected");std::vector<s16> decoded;assetCheck(h.format==1 && Native::decodeJasStreamPcm16(block.data(),block.size(),h.channels,h.block_size,h.block_size/2,decoded),"Retail first PCM block rejected");for(unsigned ch=0;ch<h.channels;++ch)for(unsigned frame=0;frame<h.block_size/2;++frame){auto*p=block.data()+32+bh._4*ch+frame*2;int value=(int(p[0])<<8)|p[1];if(value>=32768)value-=65536;assetCheck(decoded[frame*h.channels+ch]==value,"Retail PCM sample mismatch");}const uint64_t samples=h.format==0?(uint64_t(h.block_size)*16)/9:h.block_size/2;const uint64_t last=(h.loop_end-1)/samples,start=h.loop_start/samples;assetCheck(start<=last,"Loop block range invalid");const uint64_t lastOffset=64+last*length;extent(lastOffset,32,file.size);const uint64_t finalSize=file.size-lastOffset;assetCheck(finalSize<=length,"Retail final block exceeds nominal extent");auto finalBlock=disc.read(file.offset+lastOffset,size_t(finalSize));JASAramStream::BlockHeader tail{};if(!Native::decodeJasStreamBlock(finalBlock.data(),finalBlock.size(),h.channels,h.block_size,tail)){std::fprintf(stderr,"%s finalSize=%llu payload=%u channels=%u end=%d last=%llu\n",file.path.c_str(),(unsigned long long)finalSize,be32(finalBlock.data()+4),h.channels,h.loop_end,(unsigned long long)last);assetCheck(h.format==1,"Unexpected short nonPCM block");const uint64_t required=(h.loop_end-last*samples)*2,physical=(finalSize-32)/h.channels;assetCheck((finalSize-32)%h.channels==0,"Unequal physical channel lengths");std::fprintf(stderr,"DETAIL totalSamples=%u headerPayload=%u required=%llu physical=%llu deficit=%llu loop=%u\n",be32(bytes.data()+20),be32(bytes.data()+4),(unsigned long long)required,(unsigned long long)physical,(unsigned long long)(32+uint64_t(be32(finalBlock.data()+4))*h.channels-finalSize),h.loop);++shorts;++count;continue;}std::fprintf(stderr,"TAIL %s actual=%llu declared=%llu extra=%lld samples=%llu\n",file.path.c_str(),(unsigned long long)finalSize,(unsigned long long)(uint64_t(tail._4)*h.channels+32),(long long)finalSize-(long long)(uint64_t(tail._4)*h.channels+32),(unsigned long long)(h.loop_end-last*samples));std::printf("%s channels=%u format=%u rate=%d block=%u tag=%08x\n",file.path.c_str(),h.channels,h.format,h._10,h.block_size,bh.tag);++count;}assetCheck(count==74,"Expected 74 streams");std::printf("PASS %u retail stream tail layouts including %u short tails (layout diagnosis only)\n",count,shorts);}catch(const std::exception&e){std::fprintf(stderr,"%s\n",e.what());return 1;}}






